diff --git a/client.mjs b/client.mjs
index 9ad81d0..a205110 100644
--- a/client.mjs
+++ b/client.mjs
@@ -0,0 +1,2 @@
+import { sleep as realSleep } from './util.mjs';
+
@@ -12,4 +14,26 @@ export class HttpError extends Error {
-export async function fetchJson(url, { fetch = globalThis.fetch, headers = {} } = {}) {
-  const res = await fetch(url, { headers: { accept: 'application/json', ...headers } });
-  if (!res.ok) throw new HttpError(res.status, url);
-  return res.json();
+export async function fetchJson(url, { fetch = globalThis.fetch, sleep = realSleep, headers = {} } = {}) {
+  const maxRetries = 3;
+  let lastError;
+  
+  for (let attempt = 0; attempt <= maxRetries; attempt++) {
+    try {
+      const res = await fetch(url, { headers: { accept: 'application/json', ...headers } });
+      if (!res.ok) throw new HttpError(res.status, url);
+      return res.json();
+    } catch (err) {
+      lastError = err;
+      
+      // Don't retry 4xx errors or if we've exhausted retries
+      if (err instanceof HttpError && err.status >= 400 && err.status < 500) {
+        throw err;
+      }
+      
+      if (attempt < maxRetries) {
+        // Exponential backoff: 100ms, 200ms, 400ms
+        const backoffMs = 100 * Math.pow(2, attempt);
+        await sleep(backoffMs);
+      }
+    }
+  }
+  
+  throw lastError;
